#!/usr/bin/env sh
# Generated by harness-bridge ci generate.
# Run the local CI subset under the TTL, reaping before and after.
#
# Enforced by the bridge, so the two paths cannot drift:
#   scripts/ci/act-run.sh [args]  ==  ci act run [args]
BRIDGE="${BRIDGE:-node packages/pi-harness-bridge/bin/harness-bridge.mjs}"
exec $BRIDGE ci act run "$@"
